async function load(manual=false){textStatus('正在取得最新公開物件…');$('bmRefresh').disabled=true;$('bmRun').disabled=true;try{const url='https://raw.githubusercontent.com/dsiqke8d1w5q2zz5/jijdspwl3115djsjlp/main/01-crm/data/buyer-feed.json?t='+Date.now();let r;try{r=await fetch(url,{cache:'no-store',signal:AbortSignal.timeout(20000)});if(!r.ok)throw Error();}catch{r=await fetch('./data/buyer-feed.json',{cache:'no-store',signal:AbortSignal.timeout(10000)});}if(!r.ok)throw Error('公開資料暫時無法取得');const next=await r.json();if(next.schema!==1||!Array.isArray(next.listings)||!Array.isArray(next.sources))throw Error('資料格式不正確');feed=next;const automatic=runAutomatic();if(manual===true)runBuyer(current());const stale=Date.now()-Date.parse(feed.generatedAt)>36*3600000;textStatus((stale?'資料已超過 36 小時未更新。':'')+'最後取得：'+new Date(feed.generatedAt).toLocaleString('zh-TW')+'。已完成 '+automatic+' 位自動配對'+(manual===true?'，並完成目前買方的手動配對':'')+'。');render();}catch(e){textStatus('更新失敗：'+e.message+(feed?'，目前保留上次資料。':''));if(matches.size)render();if(!feed&&!matches.size)$('bmResults').innerHTML='<p class="bm-empty">目前無法讀取公開物件，仍可使用原站連結。</p>';}finally{$('bmRefresh').disabled=false;$('bmRun').disabled=!current();}}
