function separate(ids,enabled){const c=current(),old=structuredClone(c.buyerMatching||{}),set=new Set(old.separateListings||[]);ids.forEach(id=>enabled?set.add(id):set.delete(id));c.buyerMatching={...old,separateListings:[...set]};if(!persist()){c.buyerMatching=old;showToast('未能保存拆分設定','error');return;}render();}
